use vstd::prelude::*;

verus! {

#[verifier(publish)]
struct SFC64State {
    x0: u64,
    x1: u64,
    x2: u64,
    x3: u64,
}

fn sfc64(seed: Option<u64>) -> (state: SFC64State)
    // If no seed is provided, the state is all zeros.
    ensures
        seed.is_None() ==>
            state.x0 == 0 &&
            state.x1 == 0 &&
            state.x2 == 0 &&
            state.x3 == 0,
    // If a seed is provided, let val = seed.get_Some_0().
    //   - The first component is val if val != 0, otherwise 1.
    //   - The other components are zero.
    ensures
        seed.is_Some() ==>
        {
            let val = seed.get_Some_0();
            let desired: u64 = if val == 0 { 1 } else { val };
            state.x0 == desired &&
            state.x1 == 0 &&
            state.x2 == 0 &&
            state.x3 == 0
        },
    // In particular, when a seed is provided, the state is not the all‐zero state.
    ensures
        seed.is_Some() ==>
            !(state.x0 == 0 && state.x1 == 0 && state.x2 == 0 && state.x3 == 0),
{
    match seed {
        None => {
            // No seed: all zeros
            SFC64State { x0: 0, x1: 0, x2: 0, x3: 0 }
        }
        Some(v) => {
            // Seed provided: ensure first component is nonzero
            let x0 = if v == 0 {
                1u64
            } else {
                v
            };
            // This assertion justifies the non‐zero postcondition
            assert(x0 != 0);
            SFC64State { x0: x0, x1: 0, x2: 0, x3: 0 }
        }
    }
}

} // end verus!

